    rb(g, 0.32, 0.21, 0.006, P.brushed, -0.05, 0.75, -0.075, 0.003, -0.28);              // laptop lid
    mesh(g, new THREE.PlaneGeometry(0.3, 0.19), P.screen, -0.05, 0.858, -0.071, -0.28, 0, 0, false);
    books(g, w / 2 - 0.15, 0.75, -0.05, 3, 0.4);
    return g;
